    "level": "medium",
    "touches": [
      "wallet",
      "wallet_storage"
    ],
    "why": "Mistakes in unusable TXO segregation or CWalletTx state synchronization could miscalculate available balances, fail coin selection, or corrupt wallet database loading."
  }
